    Record atdp (R1 : bvmap 5 word) (M1 : mem) (sv21 : word) : Prop := ATDP {
      ad_st : stores_in (fun a => zwin (sp - 128) sp a \/ zwin (ds + 256) (ds + 260) a) M M1;
      ad_fill : fld SEGS M1 (ds + 256) 4 32;
